run_data:
Task::run(block_id, block);

string filename = MTsound;

if(MTsound == "custom")
  {
   filename = MYsound;
  }
else
   if(StringSubstr(filename, StringLen(filename)-4) != ".wav")
     {
      filename += ".wav";
     }

bool success = PlaySound(filename);

if(!success)
  {
   Print("Play Sound Error: " + ErrorMessage());
  }

block.onResult(ROUTE_1_PASSED);
